return {["fb14_01"]={["down"]=[[fb14_93]],["dsc"]=[[这里是少林寺前的广场，整个广场由大块的青石铺成，极为平坦。但因年代久远，都有些破损。正前方黄墙碧瓦，飞檐翘檩，正中一道二丈来宽，三丈来高的朱红杉木包铜大门。上方一块大匾，龙飞凤舞地书着『少林寺』三个大字。寺前三三两两的站着几个僧人。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb14_01]],["item1"]=[[bfitem5]],["name"]=[[广场]],["permission"]=1,["role1"]=[[fb14r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_03]]},["fb14_02"]={["dsc"]=[[这里是西侧殿。房间四周悬挂着禅门初祖、观音大士的画像，以及一些寺内元老的字画。地下散乱地放着许多蒲团，木鱼等。看来此处是本派弟子打坐修行之所。几位年轻僧人正肃容入定，看来已颇得禅宗三昧。]],["id"]=[[fb14_02]],["name"]=[[西侧殿]],["permission"]=2,["right"]=[[fb14_03]],["role1"]=[[fb14r02_1]],["role2"]=[[fb14r02_300]],["role3"]=[[fb14r02_302]],["stepMusic"]=[[jiaobu]]},["fb14_03"]={["down"]=[[fb14_01]],["dsc"]=[[这里是少林寺的前殿山门殿。殿内青砖铺地，两侧分列哼、哈二将。身躯雄伟，面相忿怒，头带宝冠，上半身裸露，手执金刚杵，一鼓鼻，一张口，露牙睁目，凶猛可畏。两边各放一红木供桌，陈列香烛，以供僧俗叩拜。自此左右各有一间偏殿，供比丘们打坐诵经之用。]],["id"]=[[fb14_03]],["item1"]=[[fb14item12]],["item2"]=[[fb14item25]],["item3"]=[[lbr03_3]],["left"]=[[fb14_02]],["name"]=[[山门殿]],["permission"]=1,["right"]=[[fb14_04]],["role1"]=[[fb14r03_1]],["role2"]=[[fb14r03_2]],["role3"]=[[lbr03_1]],["role4"]=[[lbr03_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_06]]},["fb14_04"]={["dsc"]=[[这里是东侧殿。房间四周悬挂着禅门初祖、观音大士的画像，以及一些寺内元老的字画。地下散乱地放着许多蒲团，木鱼等。看来此处是本派弟子打坐修行之所。几位年轻僧人正肃容入定，看来已颇得禅宗三昧。]],["id"]=[[fb14_04]],["left"]=[[fb14_03]],["name"]=[[东侧殿]],["permission"]=2,["role1"]=[[fb14r04_1]],["stepMusic"]=[[jiaobu]]},["fb14_05"]={["dsc"]=[[这里是一大片碑林。虽说是碑林，主要是少林历代高僧的佛塔灵藏。一座座佛塔约有二三人高，有汉白玉的，花冈石的，精工雕凿，薄薄的浮雕面上飞禽走兽，佛谒禅诗，诸佛众生，可谓无所不包。底座有须弥座的，也有莲花座的，各态纷呈。佛塔间疏疏落落的立着几块碑，有的题着几句诗。]],["id"]=[[fb14_05]],["item1"]=[[fb14item9]],["name"]=[[西碑林]],["permission"]=2,["right"]=[[fb14_06]],["role1"]=[[fb14r05_1]],["stepMusic"]=[[jiaobu]]},["fb14_06"]={["down"]=[[fb14_03]],["dsc"]=[[穿过山门殿，面前三道平行的青石台阶通向前方的一个高台。台阶上精工镂刻着麒麟，玄龟，松鹤等瑞兽，形态逼真动人。高台正中放着个二人高的青铜大香炉，前面摆着个香台，几位香客正在虔诚谟拜。再往前就是天王殿。]],["id"]=[[fb14_06]],["item1"]=[[bfr06_1]],["left"]=[[fb14_05]],["name"]=[[台阶]],["permission"]=1,["right"]=[[fb14_07]],["role1"]=[[fb14r06_1]],["role2"]=[[fb14r06_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_09]]},["fb14_07"]={["dsc"]=[[这里是一大片碑林。虽说是碑林，主要是少林历代高僧的佛塔灵藏。一座座佛塔约有二三人高，有汉白玉的，花冈石的，精工雕凿，薄薄的浮雕面上飞禽走兽，佛谒禅诗，诸佛众生，可谓无所不包。底座有须弥座的，也有莲花座的，各态纷呈。佛塔间疏疏落落的立着几块碑，有的题着几句诗。]],["id"]=[[fb14_07]],["item1"]=[[fb14item9]],["left"]=[[fb14_06]],["name"]=[[东碑林]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb14_08"]={["dsc"]=[[这里是西侧殿。房间四周悬挂着禅门初祖、观音大士的画像，以及一些寺内元老的字画。地下散乱地放着许多蒲团，木鱼等。看来此处是本派弟子打坐修行之所。几位中年和尚手持数珠，正在喃喃念经。]],["id"]=[[fb14_08]],["name"]=[[西侧殿]],["permission"]=2,["right"]=[[fb14_09]],["role1"]=[[fb14r08_1]],["stepMusic"]=[[jiaobu]]},["fb14_09"]={["down"]=[[fb14_06]],["dsc"]=[[这里是少林寺的中殿天王殿。殿内香烟燎绕，幔角叮咚。香火比前殿要旺盛的多。正前方供着个大肚子，似乎永远都笑咪咪的弥勒佛。四大天王分列两旁，分执“风调雨顺”。左右两边各有一间偏殿。]],["id"]=[[fb14_09]],["item1"]=[[fb14item12]],["left"]=[[fb14_08]],["name"]=[[天王殿]],["permission"]=1,["right"]=[[fb14_10]],["role1"]=[[fb14r09_1]],["role2"]=[[fb14r09_2]],["role3"]=[[fb14r09_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_13]]},["fb14_10"]={["dsc"]=[[这里是东侧殿。房间四周悬挂着禅门初祖、观音大士的画像，以及一些寺内元老的字画。地下散乱地放着许多蒲团，木鱼等。看来此处是本派弟子打坐修行之所。几位中年和尚手持数珠，正在喃喃念经。]],["id"]=[[fb14_10]],["left"]=[[fb14_09]],["name"]=[[东侧殿]],["permission"]=2,["role1"]=[[fb14r10_1]],["role2"]=[[fb14r10_2]],["stepMusic"]=[[jiaobu]]},["fb14_11"]={["dsc"]=[[这里是塔楼的底层，一缕缕阳光从墙上的花砖缝隙里透射进来，在青砖地上投下别致的光影，如同一格格棋盘相似。往上看，长长的木楼梯盘绕而上，似乎永无尽头。墙角，梯级都相当洁净，看来经常有僧人打扫。]],["id"]=[[fb14_11]],["name"]=[[鼓楼一层]],["permission"]=2,["right"]=[[fb14_12]],["role1"]=[[fb14r11_1]],["role2"]=[[fb14r11_2]],["role3"]=[[ybritem10]],["stepMusic"]=[[jiaobu]]},["fb14_12"]={["dsc"]=[[这是一座砖木结构的宝塔，塔高七层，塔身作八角形，飞檐翘翎，檐角上挂满了一串串小铜铃，随风叮叮作响。塔身墙上镂空雕绘着无数佛陀们的坐像。塔底入口处开了一扇拱形的小木门，门扇两侧用彩漆涂绘，画的是释祖在灵山对诸天众佛讲经时的情形。]],["id"]=[[fb14_12]],["left"]=[[fb14_11]],["name"]=[[鼓楼小院]],["permission"]=2,["right"]=[[fb14_13]],["role1"]=[[fb14r12_1]],["role2"]=[[fb14r12_2]],["stepMusic"]=[[jiaobu]]},["fb14_13"]={["down"]=[[fb14_09]],["dsc"]=[[过了天王殿，又有三道平行的青石台阶引正前方的一个大广场。台阶上刻的是诸天众佛，五百罗汉以及三千伽蓝的坐像。上了平台，正中方也有个丈许高的大香炉，香炉前的香台上，红烛高烧，香烟飘绕，几位香客正对大殿虔诚叩拜。左右各通向一个小院，两座高塔高耸天际。正前方就是大雄宝殿。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb14_13]],["left"]=[[fb14_12]],["name"]=[[广场]],["permission"]=1,["right"]=[[fb14_14]],["rightUp"]=[[fb14_16]],["role1"]=[[fb14r13_1]],["role2"]=[[fb14r13_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_17]]},["fb14_14"]={["dsc"]=[[这是一座砖木结构的宝塔，塔高七层，塔身作八角形，飞檐翘翎，檐角上挂满了一串串小铜铃，随风叮叮作响。塔身墙上镂空雕绘着无数佛陀们的坐像。塔底入口处开了一扇拱形的小木门，门扇两侧用彩漆涂绘，画的是释祖在灵山对诸天众佛讲经时的情形。]],["id"]=[[fb14_14]],["left"]=[[fb14_13]],["name"]=[[钟楼小院]],["permission"]=2,["right"]=[[fb14_15]],["role1"]=[[fb14r14_1]],["role2"]=[[fb14r14_2]],["stepMusic"]=[[jiaobu]]},["fb14_15"]={["dsc"]=[[这里是塔楼的底层，一缕缕阳光从墙上的花砖缝隙里透射进来，在青砖地上投下别致的光影，如同一格格棋盘相似。往上看，长长的木楼梯盘绕而上，似乎永无尽头。墙角，梯级都相当洁净，看来经常有僧人打扫。]],["id"]=[[fb14_15]],["left"]=[[fb14_14]],["name"]=[[钟楼一层]],["permission"]=2,["role1"]=[[fb14r15_1]],["role2"]=[[fb14r15_2]],["stepMusic"]=[[jiaobu]]},["fb14_16"]={["dsc"]=[[这里是少林寺的大雄宝殿。正中供奉着如来三宝，左右各是文殊、普贤菩萨。一群青衣小和尚们正在佛像前的地上诵经。缕缕香烟与梵唱交错在一起，仰视佛祖拈花浅笑的面容，令人顿时生起几分脱俗之感。身边经常有一队队僧人鱼贯而入，看他们手持戒刀，似乎是巡寺的僧人。]],["id"]=[[fb14_16]],["item1"]=[[fb14item12]],["leftDown"]=[[fb14_13]],["name"]=[[大雄宝殿]],["permission"]=2,["role1"]=[[fb14r16_1]],["role2"]=[[fb14r16_2]],["role3"]=[[ybritem2]],["stepMusic"]=[[jiaobu]]},["fb14_17"]={["down"]=[[fb14_13]],["dsc"]=[[这是戒律院前的勤修场。这里是全寺交通最密集的地方，只见一队队僧人来来去去，身着各种服色，有的携带刀，枪，棍，杖等兵器，个个身姿矫健，神态庄重。北面的大殿就是戒律院，四位僧兵持刀守在两侧。西边通向斋厅。]],["fightBackground"]=[[擂台]],["id"]=[[fb14_17]],["item1"]=[[fb14item302]],["left"]=[[fb14_18]],["name"]=[[勤修场]],["permission"]=1,["rightUp"]=[[fb14_22]],["role1"]=[[fb14r17_1]],["role2"]=[[fb14r17_2]],["role3"]=[[ybritem3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_21]]},["fb14_18"]={["dsc"]=[[这里便是少林全寺寺僧用斋的地方。斋厅极大，足可容纳上千人同时进餐。但此时还未到饭点，这儿也没什么人。]],["id"]=[[fb14_18]],["name"]=[[斋厅]],["permission"]=2,["right"]=[[fb14_17]],["role1"]=[[fb14r18_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_19]]},["fb14_19"]={["down"]=[[fb14_18]],["dsc"]=[[这里便是少林全寺寺僧用斋的地方。斋厅极大，足可容纳上千人同时进餐。但此时还未到饭点，这儿也没什么人。北面是个厨房。]],["id"]=[[fb14_19]],["name"]=[[斋厅]],["permission"]=2,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_20]]},["fb14_20"]={["down"]=[[fb14_19]],["dsc"]=[[炊烟缭绕，蒸汽腾腾，香味扑鼻而来。靠墙是一排数丈长的灶台，支着十来口大锅，最大的一口饭锅上方竟有人从梁上悬空而下，手持木棍在搅拌。除了烧饭的僧人外，几位火工头陀忙着劈柴运薪，灶下炉火熊熊。一位中年僧人正来回催促着。]],["id"]=[[fb14_20]],["name"]=[[厨房]],["permission"]=2,["role1"]=[[fb14r20_1]],["role2"]=[[fb14r20_100]],["stepMusic"]=[[jiaobu]]},["fb14_21"]={["down"]=[[fb14_17]],["dsc"]=[[这是后殿前的精进场，广场青砖铺地，因为多年的踩踏而凹凸不平。前后各是两堵高墙，把整个广场夹在中间，形成一个窄窄的长方形。西边开了扇小门，一股香气袅袅地飘了过来。北面是个大门，几位僧人在此把守。]],["id"]=[[fb14_21]],["name"]=[[精进场]],["permission"]=1,["role1"]=[[fb14r21_1]],["role2"]=[[fb14r21_2]],["role3"]=[[ybritem1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_25]]},["fb14_22"]={["dsc"]=[[整个大殿门户紧闭，密不透风。即便是在白昼，也犹如黑夜一般，每隔几步的墙上，点燃着几枝牛油巨烛。下方摆着一排排烙铁、水牛皮鞭、穿孔竹板及狼牙棒等刑具。四周站满了手持兵刃的执法僧兵。他们正用冷酷的眼神打量着你，令你不禁浑身哆嗦起来。]],["id"]=[[fb14_22]],["leftDown"]=[[fb14_17]],["name"]=[[戒律院]],["permission"]=2,["role1"]=[[fb14r22_1]],["stepMusic"]=[[jiaobu]]},["fb14_23"]={["dsc"]=[[这里是禅房走廊。房顶一侧支在南面的高墙上，另一侧则与北边般若堂的屋顶相连。彩梁画栋，连顶棚也用彩漆绘满了各种飞天的图形，每幅画似乎都在诉说一个娓娓动人的佛经故事。南边墙上题着一个字。往北通往般若堂。]],["id"]=[[fb14_23]],["name"]=[[走廊]],["permission"]=2,["right"]=[[fb14_24]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_28]]},["fb14_24"]={["dsc"]=[[这里是禅房走廊。房顶一侧支在南面的高墙上，另一侧凌空架在几根细细的石柱上。彩梁画栋，连顶棚也用彩漆绘满了各种飞天的图形，每幅画似乎都在诉说一个娓娓动人的佛经故事。南边墙上也画着一幅画。北望可以观赏僧众们练武的场面。]],["id"]=[[fb14_24]],["left"]=[[fb14_23]],["name"]=[[走廊]],["permission"]=2,["right"]=[[fb14_25]],["role1"]=[[fb14r24_1]],["role2"]=[[fb14r24_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_37]]},["fb14_25"]={["down"]=[[fb14_21]],["dsc"]=[[后殿规模不大。两边都是水磨石壁，镂刻着十八罗汉的肖像及佛谒，正中有一口水井，水面净如明镜，纯若菩提，名曰佛心乃寺内有名的清水井。东西面各有个门洞，通向两侧长长的走廊。]],["id"]=[[fb14_25]],["left"]=[[fb14_24]],["name"]=[[后殿]],["permission"]=1,["right"]=[[fb14_26]],["role1"]=[[fb14r25_1]],["role2"]=[[fb14r25_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_38]]},["fb14_26"]={["dsc"]=[[这里是禅房走廊。房顶一侧支在南面的高墙上，另一侧则与北边和尚院的屋顶相连。彩梁画栋，连顶棚也用彩漆绘满了各种飞天的图形，每幅画似乎都在诉说一个娓娓动人的佛经故事。南边墙上挂着一幅对子。北望可以观赏僧众们练武的场面。]],["id"]=[[fb14_26]],["left"]=[[fb14_25]],["name"]=[[走廊]],["permission"]=2,["right"]=[[fb14_27]],["role1"]=[[fb14r26_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_39]]},["fb14_27"]={["dsc"]=[[这里是禅房走廊。房顶一侧支在南面的高墙上，另一侧则与北边罗汉堂的屋顶相连。彩梁画栋，连顶棚也用彩漆绘满了各种飞天的图形，每幅画似乎都在诉说一个娓娓动人的佛经故事。南边墙上题着一首诗。往北通往罗汉堂。]],["id"]=[[fb14_27]],["left"]=[[fb14_26]],["name"]=[[走廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb14_40]]},["fb14_28"]={["down"]=[[fb14_23]],["dsc"]=[[这是一间极为简陋的禅房。环视四周，除了几幅佛竭外，室内空荡荡地别无他物。地上整齐的摆放着几个破烂且发黑的黄布蒲团，几位须发花白的老僧正在坐在上面闭目入定。这里是本寺十八罗汉参禅修行的地方，不少绝世武功便是在此悟出。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb14_28]],["name"]=[[般若堂一部]],["permission"]=2,["role1"]=[[fb14r28_1]],["role2"]=[[fb14r28_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_29]]},["fb14_29"]={["down"]=[[fb14_28]],["dsc"]=[[这是一间极为简陋的禅房。环视四周，除了几幅佛竭外，室内空荡荡地别无他物。地上整齐的摆放着几个破烂且发黑的黄布蒲团，几位须发花白的老僧正在坐在上面闭目入定。这里是本寺十八罗汉参禅修行的地方，不少绝世武功便是在此悟出。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb14_29]],["name"]=[[般若堂二部]],["permission"]=2,["role1"]=[[fb14r29_1]],["role2"]=[[fb14r29_2]],["role3"]=[[fb14r29_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_30]]},["fb14_30"]={["down"]=[[fb14_29]],["dsc"]=[[这是一间极为简陋的禅房。环视四周，除了几幅佛竭外，室内空荡荡地别无他物。地上整齐的摆放着几个破烂且发黑的黄布蒲团，几位须发花白的老僧正在坐在上面闭目入定。这里是本寺十八罗汉参禅修行的地方，不少绝世武功便是在此悟出。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb14_30]],["name"]=[[般若堂三部]],["permission"]=2,["role1"]=[[fb14r30_1]],["role2"]=[[fb14r30_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_31]]},["fb14_31"]={["down"]=[[fb14_30]],["dsc"]=[[这是一间极为简陋的禅房。环视四周，除了几幅佛竭外，室内空荡荡地别无他物。地上整齐的摆放着几个破烂且发黑的黄布蒲团，几位须发花白的老僧正在坐在上面闭目入定。这里是本寺十八罗汉参禅修行的地方，不少绝世武功便是在此悟出。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb14_31]],["name"]=[[般若堂四部]],["permission"]=2,["role1"]=[[fb14r31_1]],["role2"]=[[fb14r31_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_32]]},["fb14_32"]={["down"]=[[fb14_31]],["dsc"]=[[这是一间极为简陋的禅房。环视四周，除了几幅佛竭外，室内空荡荡地别无他物。地上整齐的摆放着几个破烂且发黑的黄布蒲团，几位须发花白的老僧正在坐在上面闭目入定。这里是本寺十八罗汉参禅修行的地方，不少绝世武功便是在此悟出。一位小沙弥在一边垂手站立。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb14_32]],["name"]=[[般若堂五部]],["permission"]=2,["right"]=[[fb14_37]],["role1"]=[[fb14r32_1]],["role2"]=[[fb14r32_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_