p"]=[[fb14_61]]},["fb14_51"]={["down"]=[[fb14_38]],["dsc"]=[[这里的地上整整齐齐的排放着数十个黄布蒲团，北首有一个红木讲坛，讲坛上放着个竹制的木鱼。东西边各放着一对美轮美奂的大花瓶，上插檀香数枝，香烟缭绕，氤氲芬芳，室内一片祥和之气。看来这里是方丈对僧众讲经说法的地方。]],["id"]=[[fb14_51]],["left"]=[[fb14_50]],["name"]=[[方丈楼]],["permission"]=2,["right"]=[[fb14_54]],["rightDown"]=[[fb14_52]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_64]]},["fb14_52"]={["down"]=[[fb14_53]],["dsc"]=[[这里是方丈待客的地方，靠墙左右两侧摆着一溜太师椅。北面墙上挂了一副对联。墙角一几，放着几个茶壶。有个茶壶壶身上题了“碧螺春”三个篆字，壶嘴热气腾腾，似乎是刚沏的新茶。往南是方丈室。]],["id"]=[[fb14_52]],["item1"]=[[fb14item6]],["item2"]=[[fb14item6]],["leftUp"]=[[fb14_51]],["name"]=[[茶室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb14_53"]={["dsc"]=[[方丈室陈设简洁，正中一几，一蒲团，一矮床。北面墙上写着大大的一个『禅』字。一位慈眉善目的灰衣老僧正端坐于蒲团上打坐。]],["id"]=[[fb14_53]],["item1"]=[[fb14item6]],["item2"]=[[fb14item6]],["name"]=[[方丈室]],["permission"]=2,["role1"]=[[fb14r53_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_52]]},["fb14_54"]={["down"]=[[fb14_39]],["dsc"]=[[这里是禅房走廊。走廊南侧的房顶倚着南面的高墙，另一侧则与北边和尚院的屋顶相连。南面墙上挂了一副对联:“灵根孕育源流出，心性修持大道生”。往北通向和尚院。]],["id"]=[[fb14_54]],["left"]=[[fb14_51]],["name"]=[[走廊]],["permission"]=2,["right"]=[[fb14_55]],["role1"]=[[fb14r54_1]],["role2"]=[[fb14r54_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_65]]},["fb14_55"]={["down"]=[[fb14_48]],["dsc"]=[[这里是禅房走廊。走廊南侧的房顶倚着南面的高墙，另一侧凌空架在几根细细的石柱上，倚在栏杆上，北望是一大片竹林，馨香满怀，竹影摇曳，诗意顿上心头，别有一番韵趣。]],["id"]=[[fb14_55]],["left"]=[[fb14_54]],["name"]=[[走廊]],["permission"]=2,["role1"]=[[fb14r55_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_56]]},["fb14_56"]={["down"]=[[fb14_55]],["dsc"]=[[这是一条卵石铺成的小道，曲曲折折地通向前方。两边是密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["id"]=[[fb14_56]],["left"]=[[fb14_65]],["name"]=[[竹林小道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb14_57]]},["fb14_57"]={["down"]=[[fb14_56]],["dsc"]=[[这是一条卵石铺成的小道，曲曲折折地通向前方。两边是密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["id"]=[[fb14_57]],["left"]=[[fb14_66]],["name"]=[[竹林小道]],["permission"]=2,["right"]=[[fb14_71]],["role1"]=[[fb14r57_1]],["role2"]=[[fb14r57_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_58]]},["fb14_58"]={["down"]=[[fb14_57]],["dsc"]=[[这是一条卵石铺成的小道，曲曲折折地通向前方。两边是密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["id"]=[[fb14_58]],["left"]=[[fb14_67]],["name"]=[[竹林小道]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb14_59"]={["dsc"]=[[不愧为中原佛法的总源，少林寺此处藏经之富，天下罕有其匹。这里都是密密麻麻，高及顶棚的书架，书架间仅有容身一人通行的空隙。几排大书架中间，间隔地放着数丈长的书桌。目光及处，你看到桌上放了几本佛经。]],["id"]=[[fb14_59]],["item1"]=[[bfitem1]],["name"]=[[藏经阁一楼]],["permission"]=2,["right"]=[[fb14_69]],["role1"]=[[fb14r59_1]],["role2"]=[[bfr59_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_60]]},["fb14_60"]={["down"]=[[fb14_59]],["dsc"]=[[千余年来少林寺执中原武林之牛耳，自达摩老祖以下，历代人材辈出。其中有不少高僧遗著留存，汇集至今，终成名震天下的少林七十二绝艺。少林精华，尽集于此。二楼四面开窗，确保通风。中间排列着五排大书架。四周则陈列矮几，以供阅读。几位老僧手执经卷，正在闭目凝思。]],["id"]=[[fb14_60]],["item1"]=[[fb14item7]],["name"]=[[藏经阁二楼]],["permission"]=2,["role1"]=[[fb14r60_1]],["stepMusic"]=[[jiaobu]]},["fb14_61"]={["down"]=[[fb14_50]],["dsc"]=[[这里是和尚院待客的地方，靠墙左右两侧摆着一溜太师椅。墙角一几，放着几个茶壶。有个茶壶壶身上题了“碧螺春”三个篆字，壶嘴热气腾腾，似乎是刚沏的新茶。一位小沙弥在一边垂手站立。]],["id"]=[[fb14_61]],["left"]=[[fb14_68]],["name"]=[[和尚院四部]],["permission"]=2,["right"]=[[fb14_64]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_62]]},["fb14_62"]={["down"]=[[fb14_61]],["dsc"]=[[这里是僧众们饮食起居的地方。靠墙一溜摆着几张木床，床上铺的是篾席。床头叠着床薄被，冬天想必很冷，僧侣们全靠扎实的内功根基御寒。地上整齐的放着几个蒲团和木鱼。]],["id"]=[[fb14_62]],["left"]=[[fb14_69]],["name"]=[[和尚院五部]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb14_63]]},["fb14_63"]={["down"]=[[fb14_62]],["dsc"]=[[这里是僧众们饮食起居的地方。靠墙一溜摆着几张木床，床上铺的是篾席。床头叠着床薄被，冬天想必很冷，僧侣们全靠扎实的内功根基御寒。地上整齐的放着几个蒲团和木鱼。]],["id"]=[[fb14_63]],["left"]=[[fb14_70]],["name"]=[[和尚院六部]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb14_64"]={["down"]=[[fb14_51]],["dsc"]=[[这里是少林寺的练武场。由无数块巨大的花岗岩石板铺就。上千年的踩踏已使得这些石板如同镜子般平整光滑。练武场中间竖立着不少木人和草靶。西边角上还有两个大沙坑，十来个僧人正在练习武艺。东西两面各有一长溜僧房。]],["fightBackground"]=[[擂台]],["id"]=[[fb14_64]],["item1"]=[[fb14item10]],["left"]=[[fb14_61]],["name"]=[[练武场]],["permission"]=2,["right"]=[[fb14_65]],["rightUp"]=[[fb14_76]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_75]]},["fb14_65"]={["down"]=[[fb14_54]],["dsc"]=[[这里是和尚院待客的地方，靠墙左右两侧摆着一溜太师椅。墙角一几，放着几个茶壶。有个茶壶壶身上题了“碧螺春”三个篆字，壶嘴热气腾腾，似乎是刚沏的新茶。一位小沙弥在一边垂手站立。]],["id"]=[[fb14_65]],["left"]=[[fb14_64]],["name"]=[[和尚院一部]],["permission"]=2,["right"]=[[fb14_56]],["role1"]=[[fb14r65_1]],["role2"]=[[fb14r65_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_66]]},["fb14_66"]={["down"]=[[fb14_65]],["dsc"]=[[这里是僧众们饮食起居的地方。靠墙一溜摆着几张木床，床上铺的是篾席。床头叠着床薄被，冬天想必很冷，僧侣们全靠扎实的内功根基御寒。地上整齐的放着几个蒲团和木鱼。]],["id"]=[[fb14_66]],["name"]=[[和尚院二部]],["permission"]=2,["right"]=[[fb14_57]],["role1"]=[[fb14r66_1]],["role2"]=[[fb14r66_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_67]]},["fb14_67"]={["down"]=[[fb14_66]],["dsc"]=[[这里是僧众们饮食起居的地方。靠墙一溜摆着几张木床，床上铺的是篾席。床头叠着床薄被，冬天想必很冷，僧侣们全靠扎实的内功根基御寒。地上整齐的放着几个蒲团和木鱼。]],["id"]=[[fb14_67]],["name"]=[[和尚院三部]],["permission"]=2,["right"]=[[fb14_58]],["role1"]=[[fb14r67_1]],["role2"]=[[fb14r67_2]],["stepMusic"]=[[jiaobu]]},["fb14_68"]={["down"]=[[fb14_49]],["dsc"]=[[这是一条卵石铺成的小道，曲曲折折地通向前方。两边是密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["fightBackground"]=[[森林外]],["id"]=[[fb14_68]],["name"]=[[竹林小道]],["permission"]=2,["right"]=[[fb14_61]],["role1"]=[[fb14r68_1]],["role2"]=[[fb14r68_2]],["role3"]=[[fb14r68_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_69]]},["fb14_69"]={["down"]=[[fb14_68]],["dsc"]=[[这是一条卵石铺成的小道，曲曲折折地通向前方。两边是密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["fightBackground"]=[[森林外]],["id"]=[[fb14_69]],["left"]=[[fb14_59]],["name"]=[[竹林小道]],["permission"]=2,["right"]=[[fb14_62]],["role1"]=[[fb14r69_1]],["role2"]=[[fb14r69_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_70]]},["fb14_70"]={["down"]=[[fb14_69]],["dsc"]=[[这是一条卵石铺成的小道，曲曲折折地通向前方。两边是密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["fightBackground"]=[[森林外]],["id"]=[[fb14_70]],["name"]=[[竹林小道]],["permission"]=2,["right"]=[[fb14_63]],["role1"]=[[fb14r70_1]],["role2"]=[[fb14r70_2]],["stepMusic"]=[[jiaobu]]},["fb14_71"]={["dsc"]=[[少林寺的武器库可称天下第一，十八般兵器，这里可谓应有尽有。四面一望，令你顿感眼花缭乱。墙上砌了一个个小格子，每个都插满了各种各样的兵器。一位灰衣僧人正在墙角拂拭一把戒刀。看到你进来，他缓缓起身，向你迎了过来。]],["id"]=[[fb14_71]],["item1"]=[[fb14item304]],["left"]=[[fb14_57]],["name"]=[[武器库]],["permission"]=2,["role1"]=[[fb14r71_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_72]]},["fb14_72"]={["down"]=[[fb14_71]],["dsc"]=[[这是一间很大的房间，靠墙整齐地放着一个个大柜子，不少柜子门敞开着，露出里面的各种防具，品种之多，是你生平仅见。一位灰衣僧人正埋头整理一堆破损的护具。连你进来也没有注意。]],["id"]=[[fb14_72]],["name"]=[[防具库]],["permission"]=2,["role1"]=[[fb14r72_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_73]]},["fb14_73"]={["down"]=[[fb14_72]],["dsc"]=[[这里是全寺僧侣领用药品的地方。房间里弭漫着股浓浓的药味。靠墙是一排排高及房顶的药柜，每个药柜都由上百个装药的小抽屉，上面贴满了密密麻麻的各种草头药名。一位中年僧人正来回忙碌着称量药品，熬药煎汤。]],["id"]=[[fb14_73]],["name"]=[[药品库]],["permission"]=2,["role1"]=[[fb14r73_1]],["stepMusic"]=[[jiaobu]]},["fb14_74"]={["dsc"]=[[这是地藏殿。供奉地藏王菩萨。地藏王主宰阴间，手下自然有不少鬼兵鬼卒，罗列帐前。菩萨眉横煞气，手断阴阳。令人一见之下，顿觉心惊胆战，惶恐不已。]],["id"]=[[fb14_74]],["name"]=[[地藏殿]],["permission"]=2,["right"]=[[fb14_75]],["role1"]=[[fb14r74_1]],["stepMusic"]=[[jiaobu]]},["fb14_75"]={["down"]=[[fb14_64]],["dsc"]=[[这是千佛殿前的一个广场。往北上了台阶就是供奉西天诸佛的千佛殿。往西是供奉地藏王菩萨的地藏殿，往东是供奉白衣观音大士的白衣殿。这里每年都有不少香客聚集举办水陆大法会。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb14_75]],["left"]=[[fb14_74]],["name"]=[[广场]],["permission"]=2,["right"]=[[fb14_78]],["rightDown"]=[[fb14_76]],["role1"]=[[fb14r75_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_79]]},["fb14_76"]={["dsc"]=[[这是一座古朴的殿堂。西首的墙上挂满了各类武功图谱，不少白须白眉的老僧们正端坐在图谱画轴之前，似乎在苦苦思索。南北山墙是高及屋顶的大书架，走近细看，它们是各门各派的武功秘笈，屋正中摆着几张矮几诃和几个团，几位老僧正在入定中。西首有个楼梯上楼。]],["id"]=[[fb14_76]],["leftDown"]=[[fb14_64]],["leftUp"]=[[fb14_75]],["name"]=[[达摩院]],["permission"]=2,["role1"]=[[fb14r76_1]],["role2"]=[[fb14r76_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_77]]},["fb14_77"]={["down"]=[[fb14_76]],["dsc"]=[[这是一座古朴的殿堂。西首的墙上挂满了各类武功图谱，不少白须白眉的老僧们正端坐在图谱画轴之前，似乎在苦苦思索。南北山墙是高及屋顶的大书架，走近细看，它们是各门各派的武功秘笈，屋正中摆着几张矮几诃和几个团，几位老僧正在入定中。]],["id"]=[[fb14_77]],["name"]=[[二楼]],["permission"]=2,["role1"]=[[fb14r77_1]],["role2"]=[[fb14r77_2]],["stepMusic"]=[[jiaobu]]},["fb14_78"]={["dsc"]=[[这是白衣殿，供奉白衣观音大士。大士高居须弥座上，手托净瓶，眉含微愁，唇绽浅笑，仿佛对人间疾苦既存忧心，又觉释怀。殿中放了红木大香案，香案上供品齐备，香火十分旺盛。]],["id"]=[[fb14_78]],["left"]=[[fb14_75]],["name"]=[[白衣殿]],["permission"]=2,["role1"]=[[fb14r78_1]],["role2"]=[[fb14r78_2]],["stepMusic"]=[[jiaobu]]},["fb14_79"]={["down"]=[[fb14_75]],["dsc"]=[[这是千佛殿。大殿入口是朱红格扇，七宝玲珑。内里供奉的西天诸佛，计有八菩萨，四金刚，五百阿罗，三千揭谛，十一大曜，十八伽蓝，以及众优婆塞，优婆夷等。直看得你眼花缭乱。边上有道小木门。]],["id"]=[[fb14_79]],["name"]=[[千佛殿]],["permission"]=2,["role1"]=[[fb14r78_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_80]]},["fb14_80"]={["down"]=[[fb14_79]],["dsc"]=[[这是一片密密的竹林。这里人迹罕至，惟闻足底叩击路面，有僧敲木鱼声；微风吹拂竹叶，又如簌簌禅唱。令人尘心为之一涤，真是绝佳的禅修所在。]],["id"]=[[fb14_80]],["left"]=[[fb14_81]],["name"]=[[竹林]],["permission"]=2,["right"]=[[fb14_95]],["role1"]=[[fb14r80_1]],["role2"]=[[fb14r80_2]],["role3"]=[[fb14r80_3]],["stepMusic"]=[[jiaobu]]},["fb14_81"]={["dsc"]=[[这里是达摩古洞。五百年前南天竺僧人菩提达摩来到少林寺，见此风水宝地，就住下来广罗弟子，传授禅宗，开创少林寺佛教禅宗千年不败之基。禅门初祖常在此面壁悟道，一坐十年，壁间隐隐似仍可看到他面壁时的打坐姿态。除地上的几块竹片外，洞中空无一物。]],["id"]=[[fb14_81]],["name"]=[[达摩洞]],["permission"]=2,["right"]=[[fb14_80]],["role1"]=[[fb14r81_1]],["stepMusic"]=[[jiaobu]]},["fb14_82"]={["dsc"]=[[这里是佛塔底下的地下密室。密室虽小，却也五脏俱全，石桌石椅，石几石床，连室内放的几件器皿，也都是石制的。看来似乎很久以前有人在这里住过。正中的石桌上平放着一块薄薄的石板，上面好像刻着些什么。]],["id"]=[[fb14_82]],["name"]=[[地下室]],["permission"]=2,["role1"]=[[fb14r82_1]],["stepMusic"]=[[jiaobu]]},["fb14_83"]={["dsc"]=[[这里是嵩山南麓的少室山山脚。一条长长的石阶如同巨龙般蜿蜒而上，直没云端。嵩山群峰壁立，翠色满山，令人俯仰间顿生渺小之意。边上有几个叫卖的小贩和挑夫，似乎在嚷嚷着争吵些什么。]],["id"]=[[fb14_83]],["item1"]=[[dhpd]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r83_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_84]]},["fb14_84"]={["down"]=[[fb14_83]],["dsc"]=[[长长的石阶往上依然看不到尽头。身边的山壁受着长年风雨的浸润，长出了薄薄的青苔。上面依稀有些刻凿的痕迹。有一行字特别清晰:“金刚伏邪魔，宝塔镇群妖”。]],["id"]=[[fb14_84]],["item1"]=[[fb14item24]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r84_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_85]]},["fb14_85"]={["down"]=[[fb14_84]],["dsc"]=[[石级到这里似乎变得宽阔了些。清新的山风扑面而来，令人精神顿为一爽。远处传来淙淙水声，渐行渐远。山壁上挂满了厚密的藤萝，随风轻轻摇弋。]],["id"]=[[fb14_85]],["left"]=[[fb14_86]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r85_1]],["stepMusic"]=[[jiaobu]]},["fb14_86"]={["dsc"]=[[水声越来越大，山间充满了浓浓的水气。石阶上，断裂的山隙中，都流出一道道细细的泉水，汇成一股澄碧的小溪，向山下蜿蜒流去。周围绿意荡漾，鸟语鹦声，如置身仙境。]],["id"]=[[fb14_86]],["name"]=[[石阶]],["permission"]=1,["right"]=[[fb14_85]],["role1"]=[[fb14r86_1]],["role2"]=[[fb14r86_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_87]]},["fb14_87"]={["down"]=[[fb14_86]],["dsc"]=[[一挂巨大的瀑布白龙出霄般横越山间，水气已浓得仿佛可以滴下水珠儿来。山峦间升起薄薄的青雾，凝聚不散。哗哗的水声震耳欲聋。石阶上满是水渍，走上去滑得可以让人打跌…]],["id"]=[[fb14_87]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r87_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_88]]},["fb14_88"]={["down"]=[[fb14_87]],["dsc"]=[[这里是瀑布上方一道窄窄的山梁，浑然天成。石梁上面人工凿出一格格阶梯。边上钉了几棵木桩，绕上粗长的麻绳作为扶手。瀑布在脚下奔腾而过，在不远的山脚下汇成一个深潭。]],["id"]=[[fb14_88]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r88_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_89]]},["fb14_89"]={["down"]=[[fb14_88]],["dsc"]=[[石级继续向上延伸，瀑布在脚下越来越小，水声也渐行远去几位身着灰黄色僧衣的僧人擦肩而过，看他们下山的时後脚步沉稳，好像是个会家子。往上远眺，似乎可以看到石檐一角。]],["id"]=[[fb14_89]],["item1"]=[[fb14item23]],["name"]=[[石阶]],["permission"]=1,["right"]=[[fb14_94]],["role1"]=[[fb14r89_1]],["role2"]=[[ybrr89_01]],["stepMusic"]=[[jiaobu]]},["fb14_90"]={["dsc"]=[[这里看来是半山腰了。不远的前面有一座小石亭，几位游客在这里歇息。山路到这里变得十分平坦，东边的山壁上提满了名人即兴题下的诗句。远望山林间层峦迭嶂，满目滴翠。]],["id"]=[[fb14_90]],["left"]=[[fb14_94]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r90_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_91]]},["fb14_91"]={["down"]=[[fb14_90]],["dsc"]=[[眼前遽然出现一大片松林。松林长得极密，石阶上铺满了厚厚的朽黄的松针。踩在脚下，发出察察的响声。一只小松鼠吱地在眼前闪过，消失在林海里。]],["id"]=[[fb14_91]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r91_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_92]]},["fb14_92"]={["down"]=[[fb14_91]],["dsc"]=[[松树与松树似乎都挤在一块生长，阳光到这里变得格外黯淡只在地上留下斑驳的碎影。静听不远处格的一声，像是松枝断落的声音。]],["id"]=[[fb14_92]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r92_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_93]]},["fb14_93"]={["down"]=[[fb14_92]],["dsc"]=[[松林渐渐开阔，面前出现了一条宽广的石板道，笔直通向前方。沿道稀稀落落地种着几棵柏树，却显得高大挺拔，蝤龙般的枝干向天空高高伸展着。]],["id"]=[[fb14_93]],["name"]=[[石阶]],["permission"]=1,["role1"]=[[fb14r93_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_01]]},["fb14_94"]={["dsc"]=[[一个巨大的牌坊横架在两片山壁之间，牌坊正上方刻着三个斗大的字:『少林寺』。字迹有些剥落，看上去年代久远。两位三十来岁的僧人手持戒刀守在山门两侧。左侧立着一块石碑。]],["id"]=[[fb14_94]],["left"]=[[fb14_89]],["name"]=[[山门]],["permission"]=1,["right"]=[[fb14_90]],["role1"]=[[fb14r94_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_96]]},["fb14_95"]={["dsc"]=[[一座古朴的殿堂。看起来空荡荡的。一名老僧正在大殿之前扫地。此处乃是禅门初祖设下的修行之所。历任金刚院守护均以四大金刚命名，凡得到方丈认可者，方能来此学习少林无上武功。]],["id"]=[[fb14_95]],["left"]=[[fb14_80]],["name"]=[[金刚院]],["permission"]=2,["role1"]=[[dmr95_1]],["stepMusic"]=[[jiaobu]]},["fb14_96"]={["down"]=[[fb14_94]],["dsc"]=[[这里是瀑布上方一道窄窄的山梁，浑然天成。石梁上面人工凿出一格格阶梯。边上钉了几棵木桩，绕上粗长的麻绳作为扶手。瀑布在脚下奔腾而过，在不远的山脚下汇成一个深潭。]],["id"]=[[fb14_96]],["name"]=[[石阶]],["permission"]=2,["role1"]=[[fb14_86a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb14_97]]},["fb14_97"]={["down"]=[[fb14_96]],["dsc"]=[[这是千佛殿前的一个广场。往北上了台阶就是供奉西天诸佛的千佛殿。往西是供奉地藏王菩萨的地藏殿，往东是供奉白衣观音大士的白衣殿。这里每年都有不少香客聚集举办水陆大法会。]],["id"]=[[fb14_97]],["item1"]=[[fubentiaozhuan1]],["name"]=[[广场]],["permission"]=2,["stepMusic"]=[[jiaobu]]}}00000000